/**
 * The nine founder failures rendered on `/socials`.
 *
 * The rail on `/socials` shows one ball per failure in this order (the centre
 * of the sequence is the visually largest ball). Each entry also drives its own
 * `/socials/<slug>` deep-dive page, whose artwork lives in `public/socials/`
 * and is generated by `scripts/generate-failure-art.mjs`.
 */

export type FailureFrame = {
  /** File name (without extension) inside `public/socials/`. */
  frame: string;
  caption: string;
};

export type FailureStage = {
  when: string;
  what: string;
};

export type FailureRemedy = {
  /** The Altitut surface that intercepts this failure. */
  surface: string;
  how: string;
};

export type Failure = {
  slug: string;
  /** Two-word label printed inside the ball. */
  label: string;
  /** Short kicker under the ball label. */
  kicker: string;
  /** Full failure name used as the page title. */
  title: string;
  /** One-line verdict. */
  verdict: string;
  /** Punch-in-the-gut stat, shown large. */
  stat: string;
  statNote: string;
  /** The emotional opening of the deep-dive page. */
  opening: string[];
  /** What the founder tells themselves while it happens. */
  lie: string;
  /** How it actually ends. */
  ending: string;
  /** The slow-motion anatomy of the failure. */
  anatomy: FailureStage[];
  /** How Altitut intercepts it, mapped to real product surfaces. */
  remedies: FailureRemedy[];
  /** The one sentence that reframes the failure. */
  reframe: string;
  /**
   * The three "failure side" frames shown in the narrative. The hero, resolution
   * and horizon frames (`<slug>-hero`, `<slug>-resolution`, `<slug>-horizon`)
   * are derived from the slug by the page itself.
   */
  images: FailureFrame[];
};

