export const FAILURE_SLUGS = FAILURES.map((failure) => failure.slug);

export function getFailure(slug: string): Failure | undefined {
  return FAILURES.find((failure) => failure.slug === slug);
}

export function getFailureNeighbours(slug: string): {
  previous: Failure;
  next: Failure;
} {
  const index = FAILURES.findIndex((failure) => failure.slug === slug);
  const length = FAILURES.length;
  return {
    previous: FAILURES[(index - 1 + length) % length],
    next: FAILURES[(index + 1) % length],
  };
}
